from pathlib import Path
from PIL import Image,ImageFilter
from scipy.ndimage import distance_transform_edt
import numpy as np
import json,hashlib,html

ROOT=Path('/data/chenkejun/CVPR/results/scannet_repair_50_120_200_20261106')
P=ROOT/'main/scene0011_00/200/A/candidates'
OUT=ROOT/'instance_ply_comparison/erosion_review_20261106';OUT.mkdir(exist_ok=True)
cfg=json.loads(Path('/home/chenkejun/CVPR/experiments/scannet_repair_50_120_200_20261106/main/scene0011_00/selection_code/200/A/config.json').read_text());scene=Path(cfg['source']['scene_root']);poses=np.loadtxt(scene/'traj.txt').reshape(-1,4,4);ks=np.loadtxt(scene/'intrinsics.txt').reshape(-1,3,3);seeds=json.loads((P/'v1/grouping.json').read_text())['seeds'];frame_map=json.loads(Path('/data/chenkejun/CVPR/results/scannet_ovimap_strict_dbscan_20261104/inputs/scene0011_00/selection.json').read_text())['original_frames'];RATIOS=[0,1,2,5]

def load(name):
 s=next(s for s in seeds if s['id']==name);f=s['frame'];m=np.asarray(Image.open(P/'v1'/s['mask']))>0;yy,xx=np.nonzero(m);short=int(min(xx.max()-xx.min()+1,yy.max()-yy.min()+1));dist=distance_transform_edt(np.pad(m,1))[1:-1,1:-1]
 with np.load(P/'overmerge'/('frame%06d_visible.npz'%f)) as z:vis=z['vertex_index'].copy();uv=z['uv'].copy()
 return dict(name=name,frame=f,processed=f//5+1,original=frame_map[f//5],mask=m,short=short,dist=dist,rgb=Image.open(scene/'results'/('frame%06d.jpg'%f)).convert('RGB'),depth=np.asarray(Image.open(scene/'results'/('depth%06d.png'%f)),dtype=np.float64)/1000,pose=poses[f],K=ks[f],visible=vis,uv=uv,maskpath=str((P/'v1'/s['mask']).resolve()))
def eroded(s,r):
 pixels=max(1,round(s['short']*r/100)) if r else 0;return (s['dist']>pixels if pixels else s['mask']),pixels
def outline(mask):
 x=Image.fromarray(mask.astype(np.uint8)*255,'L');return np.asarray(x.filter(ImageFilter.MaxFilter(3)))>np.asarray(x.filter(ImageFilter.MinFilter(3)))
def dilate(mask):return np.asarray(Image.fromarray(mask.astype(np.uint8)*255,'L').filter(ImageFilter.MaxFilter(5)))>0
def mask_overlay(s,m,color):
 a=np.asarray(s['rgb']).copy();a[m]=(a[m].astype(float)*.48+np.array(color)*.52).astype(np.uint8);a[outline(s['mask'])]=[255,255,255];return Image.fromarray(a)
def mapping(src,dst):
 d=src['depth'];k=src['K'];k2=dst['K'];y,x=np.nonzero((d>0)&(d<10));z=d[y,x];pc=np.column_stack(((x-k[0,2])*z/k[0,0],(y-k[1,2])*z/k[1,1],z));world=pc@src['pose'][:3,:3].T+src['pose'][:3,3];q=(world-dst['pose'][:3,3])@dst['pose'][:3,:3];zz=q[:,2];f=(zz>.05)&(zz<10);uv=np.full((len(zz),2),-1,np.int32);uv[f]=np.rint(np.column_stack((k2[0,0]*q[f,0]/zz[f]+k2[0,2],k2[1,1]*q[f,1]/zz[f]+k2[1,2]))).astype(np.int32);valid=f&(uv[:,0]>=0)&(uv[:,0]<640)&(uv[:,1]>=0)&(uv[:,1]<480);i=np.flatnonzero(valid);u,v=uv[i].T;db=dst['depth'][v,u];back=np.column_stack(((u-k2[0,2])*db/k2[0,0],(v-k2[1,2])*db/k2[1,1],db));ok=(db>0)&(db<10)&(np.linalg.norm(back-q[i],axis=1)<=.02);i=i[ok];u,v=uv[i].T;domain=np.zeros((480,640),bool);domain[v,u]=True;return y[i],x[i],v,u,domain

def overlap3(a,b,ma,mb):
 va,vb=a['visible'],b['visible'];ua,ub=a['uv'],b['uv'];sa=va[ma[ua[:,1],ua[:,0]]];sb=vb[mb[ub[:,1],ub[:,0]]];inter=np.intersect1d(sa,sb,assume_unique=True).size;raw_union=len(sa)+len(sb)-inter;ca=np.intersect1d(sa,vb,assume_unique=True).size;cb=np.intersect1d(sb,va,assume_unique=True).size;co_union=ca+cb-inter
 return dict(a_points=len(sa),b_points=len(sb),intersection=int(inter),full_iou=float(inter/raw_union) if raw_union else None,covis_a=int(ca),covis_b=int(cb),covis_union=int(co_union),covis_iou=float(inter/co_union) if co_union else None)

def direction(src,dst,mapped,ma,mb,r,ra,rb):
 ys,xs,yt,xt,domain=mapped;projected=np.zeros((480,640),bool);sel=ma[ys,xs];projected[yt[sel],xt[sel]]=True;target=mb&domain;both=projected&target;onlya=projected&~target;onlyb=target&~projected;excluded=mb&~domain;uni=projected|target
 z=dict(source=src['name'],target=dst['name'],ratio=r,source_erode_px=ra,target_erode_px=rb,source_mask_before=int(src['mask'].sum()),source_mask_after=int(ma.sum()),target_mask_before=int(dst['mask'].sum()),target_mask_after=int(mb.sum()),domain_pixels=int(domain.sum()),warped_pixels=int(projected.sum()),target_in_domain=int(target.sum()),intersection=int(both.sum()),source_only=int(onlya.sum()),target_only=int(onlyb.sum()),union=int(uni.sum()),iou=float(both.sum()/uni.sum()) if uni.any() else None,uncovered_target=int(excluded.sum()))
 assert z['intersection']+z['source_only']+z['target_only']==z['union'] and z['intersection']+z['source_only']==z['warped_pixels']
 prefix=src['name']+'_to_'+dst['name']+'_r'+str(r).zfill(2);mask_overlay(src,ma,(35,164,255)).save(OUT/(prefix+'_source.png'));mask_overlay(dst,mb,(243,145,30)).save(OUT/(prefix+'_target.png'))
 arr=np.asarray(dst['rgb']).copy();arr[excluded]=(arr[excluded].astype(float)*.55+np.array([144,152,161])*.45).astype(np.uint8);arr[outline(dst['mask'])]=[255,255,255];arr[outline(mb)]=[245,185,42];arr[dilate(onlya)]=[19,156,244];arr[dilate(onlyb)]=[243,137,30];arr[dilate(both)]=[33,199,108];over=Image.fromarray(arr);over.save(OUT/(prefix+'_overlap.png'))
 yy,xx=np.nonzero(projected|dst['mask']);crop=over.crop((max(0,int(xx.min())-28),max(0,int(yy.min())-28),min(640,int(xx.max())+29),min(480,int(yy.max())+29))) if len(xx) else over;crop.save(OUT/(prefix+'_zoom.png'))
 np.savez_compressed(OUT/(prefix+'_exact.npz'),source_eroded=ma,target_eroded=mb,common=domain,warped=projected,target_in_common=target,overlap=both,source_only=onlya,target_only=onlyb,target_uncovered=excluded)
 z['prefix']=prefix;return z

ss={name:load(name) for name in ['M0053','M0092','M0126']};pairs=[('M0053','M0092'),('M0053','M0126')];dirs=[('M0053','M0092'),('M0092','M0053'),('M0053','M0126'),('M0126','M0053')];maps={a+'_'+b:mapping(ss[a],ss[b]) for a,b in dirs};result={'status':'PASS','scope':'scene0011_00 main offline 200 frames, original selected masks; read-only diagnostic','gt_used_for_calculation':False,'ratios':RATIOS,'radius_definition':'round(mask bounding-box shorter side times percentage), minimum 1 pixel for positive ratio; Euclidean distance to original mask background > radius','depth_consistency_m':.02,'results_2d':{},'results_3d':{},'masks':{}}
for n,s in ss.items():
 result['masks'][n]={'short_side':s['short'],'original_pixels':int(s['mask'].sum()),'mask_path':s['maskpath'],'sha256':hashlib.sha256(Path(s['maskpath']).read_bytes()).hexdigest(),'radii':{str(r):eroded(s,r)[1] for r in RATIOS}}
for r in RATIOS:
 er={n:eroded(s,r) for n,s in ss.items()};result['results_2d'][str(r)]=[direction(ss[a],ss[b],maps[a+'_'+b],er[a][0],er[b][0],r,er[a][1],er[b][1]) for a,b in dirs];result['results_3d'][str(r)]=[{**overlap3(ss[a],ss[b],er[a][0],er[b][0]),'a':a,'b':b} for a,b in pairs]
 print('RATIO',r,'2D',[(x['source'],x['target'],round(x['iou'],5)) for x in result['results_2d'][str(r)]],'3D',[(x['a'],x['b'],round(x['covis_iou'],5)) for x in result['results_3d'][str(r)]],flush=True)
assert [(r['intersection'],r['union']) for r in result['results_2d']['0']]==[(495,1050),(461,1095),(114,424),(130,437)]
(OUT/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
style='''*{box-sizing:border-box}body{margin:0;background:#f2f5f9;color:#26364b;font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif}.wrap{max-width:1320px;margin:auto;padding:22px}h1{font-size:23px;margin:0 0 5px;color:#1b3049}h2{font-size:18px;margin:0}p{margin:5px 0;font-size:13px;color:#60748b;line-height:1.7}.nav,.buttons,.legend{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}.nav a,button{font:inherit;font-size:13px;text-decoration:none;border:1px solid #cddae6;border-radius:7px;padding:8px 11px;background:white;color:#305a88;cursor:pointer}button.active{background:#315f9b;color:white;border-color:#315f9b}.banner,.panel{background:#fff;border:1px solid #dce5ee;border-radius:9px;padding:15px;margin:12px 0}.banner{background:#edf5ff;border-color:#d7e6f7}.legend span{font-size:12px;color:#465a70;margin-right:8px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.grid figure{margin:0;min-width:0}.grid img{width:100%;display:block;max-height:540px;object-fit:contain;background:#e9eef4;border:1px solid #dde5ec;border-radius:5px}.grid figcaption{font-size:13px;font-weight:650;color:#3d536b;margin:5px 0}.metric{background:#f3f7fb;color:#435971;border-radius:6px;padding:10px;margin:10px 0;font-size:13px}.small{font-size:12px;color:#728498}.tbl{width:100%;border-collapse:collapse;font-size:13px}.tbl td,.tbl th{text-align:left;padding:8px;border-bottom:1px solid #eaf0f5}.tbl th{color:#65778a;font-weight:600}.tbl tr.sel{background:#edf5ff}.value{font-weight:700;color:#1f5a98}.row{display:flex;justify-content:space-between;gap:10px;align-items:center}@media(max-width:800px){.grid{grid-template-columns:1fr}.wrap{padding:15px}.tablewrap{overflow:auto}.tbl{min-width:650px}}'''
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>mask 腐蚀前后投影对照</title><style>'''+style+'''</style></head><body><main class="wrap"><h1>mask 内腐蚀：双向投影对照</h1><p>scene0011_00 · main 离线 200 帧 · 原实验种子 · 仅诊断，未改算法</p><nav class="nav"><a href="../warp_review_20261106/">← 返回未腐蚀的投影页</a><a href="#summary">跳到数据汇总</a><a href="#case0">同椅子 · 正向</a><a href="#case1">同椅子 · 反向</a><a href="#case2">不同实例 · 正向</a><a href="#case3">不同实例 · 反向</a></nav><div class="banner"><p><b>腐蚀方式：</b>同时腐蚀两边 mask；半径 = 各自 mask 包围框短边 × 比例，四舍五入到像素，正比例最少 1 像素；用欧氏距离做向内腐蚀。以 1% 为例，M0053、M0092、M0126 的半径分别为 2、1、2 像素。0% 表示原 mask。</p><p>投影沿用原来的位姿、深度和 2 cm 深度一致性；各比例使用相同共同可见投影范围。<b>二维双向 IoU</b>以目标视角像素计算；<b>三维共同可见 IoU</b>以 TSDF 表面点索引计算，数值不能混用。GT 仅用于事后判断示例是否同实例。</p><p>白色轮廓是未腐蚀的原 mask；源图蓝色和目标图橙色表示腐蚀后的 mask。投影图中绿色是双方重合、蓝色仅源投影、橙色仅目标、灰色是目标 mask 中未被本次投影覆盖的部分。彩色点为展示加粗，所有数值按未加粗的原始像素计算。</p></div><div class="buttons"><strong>选择腐蚀比例：</strong><button data-r="0">0% 原始</button><button data-r="1" class="active">1%</button><button data-r="2">2%</button><button data-r="5">5%</button><span id="radii" class="small"></span></div><section id="summary" class="panel"><h2>各比例的数据对照</h2><div class="tablewrap"><table class="tbl"><thead><tr><th>腐蚀比例</th><th>同椅子 A→B</th><th>同椅子 B→A</th><th>不同实例 A→B</th><th>不同实例 B→A</th><th>同椅子 3D</th><th>不同实例 3D</th></tr></thead><tbody id="summarybody"></tbody></table></div><p class="small">A = M0053；同椅子 B = M0092；不同实例 B = M0126。前四列为共同可见投影像素 IoU，后两列为共同可见 TSDF 点 IoU；仅两个例子，不能据此确定通用阈值。</p></section><div id="cases"></div></main><script>
const labels=['同椅子 · M0053 → M0092','同椅子 · M0092 → M0053','不同实例 · M0053 → M0126','不同实例 · M0126 → M0053'];let result,current=1;const fmt=x=>x==null?'无法计算':Number(x).toFixed(3);const pct=(a,b)=>(a/b*100).toFixed(1)+'%';
function render(){document.querySelectorAll('button[data-r]').forEach(b=>b.classList.toggle('active',Number(b.dataset.r)===current));document.querySelector('#radii').textContent='半径：M0053 '+result.masks.M0053.radii[current]+' px · M0092 '+result.masks.M0092.radii[current]+' px · M0126 '+result.masks.M0126.radii[current]+' px';let body=document.querySelector('#summarybody');body.replaceChildren();result.ratios.forEach(r=>{let tr=document.createElement('tr');if(r===current)tr.className='sel';let d=result.results_2d[String(r)],t=result.results_3d[String(r)],vals=[r+'%',...d.map(x=>fmt(x.iou)),...t.map(x=>fmt(x.covis_iou))];vals.forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});body.append(tr)});let root=document.querySelector('#cases');root.replaceChildren();result.results_2d[String(current)].forEach((s,i)=>{let sec=document.createElement('section');sec.id='case'+i;sec.className='panel';let images=[['源视角：原 mask 白轮廓 / 腐蚀后蓝色','source'],['目标视角：原 mask 白轮廓 / 腐蚀后橙色','target'],['目标视角：投影与重合','overlap'],['重合区域局部放大','zoom']].map(([title,key])=>'<figure><figcaption>'+title+'</figcaption><a target="_blank" href="./'+s.prefix+'_'+key+'.png"><img loading="lazy" src="./'+s.prefix+'_'+key+'.png" alt="'+title+'"></a></figure>').join('');sec.innerHTML='<div class="row"><h2>'+labels[i]+'</h2><span class="value">二维 IoU '+fmt(s.iou)+'</span></div><p>源 mask：'+s.source_mask_before.toLocaleString()+' → '+s.source_mask_after.toLocaleString()+' 像素（保留 '+pct(s.source_mask_after,s.source_mask_before)+'）；目标 mask：'+s.target_mask_before.toLocaleString()+' → '+s.target_mask_after.toLocaleString()+' 像素（保留 '+pct(s.target_mask_after,s.target_mask_before)+'）。</p><div class="metric">源投影 '+s.warped_pixels+' · 目标共同可见 '+s.target_in_domain+' · 交集 <b>'+s.intersection+'</b> · 并集 <b>'+s.union+'</b> · 二维 IoU <b>'+s.intersection+' / '+s.union+' = '+fmt(s.iou)+'</b></div><div class="grid">'+images+'</div><p class="small">目标 mask 有 '+s.uncovered_target+' 个腐蚀后像素不在本次投影覆盖范围中，不纳入 IoU；它们可能包含采样空洞，不能直接视作不可见。</p>';root.append(sec)})}
document.querySelectorAll('button[data-r]').forEach(b=>b.onclick=()=>{current=Number(b.dataset.r);render()});fetch('./results.json').then(r=>{if(!r.ok)throw Error('无法读取诊断结果');return r.json()}).then(x=>{result=x;render()}).catch(e=>document.querySelector('#radii').textContent=e.message);
</script></body></html>'''
